    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 1 },
    ],
  });
  assert.equal(r.ok, false);
  assert.equal(r.error, 'UNKNOWN_SKU');
});

